#[derive(Debug, Clone)]
struct MatchRange {
    start: usize,
    end: usize,
}
#[derive(Debug, Clone)]
struct LineMatch {
    line_number: usize, // 0-indexed
    line_content: String,
    matches: Vec<MatchRange>, // byte ranges in line
}
#[derive(Debug, Clone)]
struct FileResult {
