            let horiz_top = Layout::default()
                .direction(Direction::Horizontal)
                .constraints([Constraint::Percentage(35), Constraint::Percentage(65)])
                .split(top_area);
            let left_top = horiz_top[0];
            let right_top = horiz_top[1];

            let left_vert_top = Layout::default()
                .direction(Direction::Vertical)
                .constraints([Constraint::Length(3), Constraint::Length(3), Constraint::Min(0)])
                .split(left_top);

            let search_area2 = left_vert_top[0];
            let replace_area2 = left_vert_top[1];
            let result_area2 = left_vert_top[2];

            // Search box
            let search_title = format!("Search [{}]", search_mode.as_str());
            let search_block = Block::default()
                .borders(Borders::ALL)
                .border_style(if focus == Focus::Search && !show_help && confirm_dialog.is_none() { Style::default().fg(Color::Green).add_modifier(Modifier::BOLD) } else { Style::default() })
                .title(search_title);
            let search_para = Paragraph::new(search_text.as_str()).block(search_block);
            f.render_widget(search_para, search_area2);

            // Replace box
            let replace_title = format!("Replace [{}]", replace_mode.as_str());
            let replace_block = Block::default()
                .borders(Borders::ALL)
                .border_style(if focus == Focus::Replace && !show_help && confirm_dialog.is_none() { Style::default().fg(Color::Green).add_modifier(Modifier::BOLD) } else { Style::default() })
                .title(replace_title);
            let replace_content = if replace_mode == ReplaceMode::DeleteLine {
                "[Entire line will be deleted]".to_string()
            } else {
                replace_text.clone()
            };
            let replace_para = Paragraph::new(replace_content).block(replace_block);
            f.render_widget(replace_para, replace_area2);

            // Result List
            let result_block = Block::default()
                .borders(Borders::ALL)
                .border_style(if focus == Focus::ResultList && !show_help && confirm_dialog.is_none() { Style::default().fg(Color::Green).add_modifier(Modifier::BOLD) } else { Style::default() })
                .title("Result List");
            f.render_widget(result_block.clone(), result_area2);
            let inner_result = result_block.inner(result_area2);
            // Build lines for result list
            let mut lines = Vec::new();
            for (idx, fr) in search_results.iter().enumerate() {
                if deleted_files.contains(&idx) {
                    continue;
                }
                // Check if all lines deleted?
                let deleted_set = deleted_lines.get(&idx);
                let remaining_lines: Vec<&LineMatch> = fr.line_matches.iter().filter(|lm| {
                    if let Some(set) = deleted_set {
                        !set.contains(&lm.line_number)
                    } else { true }
                }).collect();
                if remaining_lines.is_empty() && !fr.line_matches.is_empty() {
                    // If all lines deleted, skip file? Or show file with 0?
                    // For file list, if all lines deleted, file should be considered removed? We'll skip.
                    continue;
                }
                let display = format!("{} ({})", fr.rel_path, fr.total_matches); // but should adjust for deleted lines? For simplicity keep total
                // Count remaining?
                let remaining_count = remaining_lines.iter().map(|lm| lm.matches.len()).sum::<usize>();
                // If we have deleted lines, adjust count?
                // For display, use remaining_count if deleted, else total
                let count_to_show = if deleted_set.is_some() { remaining_count } else { fr.total_matches };
                let display = format!("{} ({})", fr.rel_path, count_to_show);
                let style = if focus == Focus::ResultList && !show_help && confirm_dialog.is_none() && result_state == ResultListState::FileList && file_selected == idx {
                    Style::default().bg(Color::Blue).fg(Color::White)
                } else {
                    Style::default()
                };
                lines.push(Line::from(Span::styled(display, style)));
            }
            let result_para = Paragraph::new(lines).block(Block::default());
            f.render_widget(result_para, inner_result);

            // Preview
            let preview_block = Block::default()
                .borders(Borders::ALL)
                .title("Preview");
            f.render_widget(preview_block.clone(), right_top);
            let inner_preview = preview_block.inner(right_top);
            // Build preview content based on selection
            let mut preview_lines: Vec<Line> = Vec::new();
            if !search_results.is_empty() {
                if result_state == ResultListState::FileList {
                    // Show matching lines of selected file
                    if file_selected < search_results.len() && !deleted_files.contains(&file_selected) {
                        let fr = &search_results[file_selected];
                        let deleted_set = deleted_lines.get(&file_selected);
                        for lm in &fr.line_matches {
                            if let Some(set) = deleted_set {
                                if set.contains(&lm.line_number) { continue; }
                            }
                            // Preview line: show line number and content with replacement preview
                            // For simplicity, show original line with matches highlighted and replacement if any
                            let mut spans = Vec::new();
                            spans.push(Span::raw(format!("   {} ", lm.line_number+1)));
                            // If replace mode and replace text not empty or delete, show diff
                            if replace_mode != ReplaceMode::DeleteLine && !replace_text.is_empty() {
                                // Build diff view: for each match, show original struck and replacement
                                let mut last = 0;
                                // Sort matches
                                let mut ms = lm.matches.clone();
                                ms.sort_by_key(|m| m.start);
                                for mr in ms {
                                    if mr.start < last { continue; }
                                    if mr.start > last {
                                        spans.push(Span::raw(lm.line_content[last..mr.start].to_string()));
                                    }
                                    let orig = &lm.line_content[mr.start..mr.end];
                                    // Original with red bg and strikethrough
                                    spans.push(Span::styled(orig.to_string(), Style::default().fg(Color::White).bg(Color::Red).add_modifier(Modifier::CROSSED_OUT)));
                                    let repl = match replace_mode {
                                        ReplaceMode::Simple => replace_text.clone(),
                                        ReplaceMode::PreserveCase => preserve_case(orig, &replace_text),
                                        ReplaceMode::DeleteLine => String::new(),
                                    };
                                    spans.push(Span::styled(repl, Style::default().fg(Color::White).bg(Color::Green)));
                                    last = mr.end;
                                }
                                if last < lm.line_content.len() {
                                    spans.push(Span::raw(lm.line_content[last..].to_string()));
                                }
                            } else if replace_mode == ReplaceMode::DeleteLine {
                                spans.push(Span::styled(lm.line_content.clone(), Style::default().fg(Color::Red).add_modifier(Modifier::CROSSED_OUT)));
                            } else {
                                // No replacement, just show line with matches highlighted
                                let mut last = 0;
                                let mut ms = lm.matches.clone();
                                ms.sort_by_key(|m| m.start);
                                for mr in ms {
                                    if mr.start < last { continue; }
                                    if mr.start > last {
                                        spans.push(Span::raw(lm.line_content[last..mr.start].to_string()));
                                    }
                                    spans.push(Span::styled(lm.line_content[mr.start..mr.end].to_string(), Style::default().bg(Color::Yellow).fg(Color::Black)));
                                    last = mr.end;
                                }
                                if last < lm.line_content.len() {
                                    spans.push(Span::raw(lm.line_content[last..].to_string()));
                                }
                            }
                            preview_lines.push(Line::from(spans));
                        }
                    }
                } else {
                    // LineList mode: opened file
                    if let Some(open_idx) = opened_file {
                        if open_idx < search_results.len() {
                            let fr = &search_results[open_idx];
                            let deleted_set = deleted_lines.get(&open_idx);
                            let filtered: Vec<&LineMatch> = fr.line_matches.iter().filter(|lm| {
                                if let Some(set) = deleted_set {
                                    !set.contains(&lm.line_number)
                                } else { true }
                            }).collect();
                            for (idx, lm) in filtered.iter().enumerate() {
                                let is_selected = idx == line_selected;
                                let prefix = if is_selected { "> " } else { "  " };
                                let mut spans = Vec::new();
                                spans.push(Span::raw(format!("{}{} ", prefix, lm.line_number+1)));
                                // Show line with replacement preview as before
                                if replace_mode != ReplaceMode::DeleteLine && !replace_text.is_empty() {
                                    let mut last = 0;
                                    let mut ms = lm.matches.clone();
                                    ms.sort_by_key(|m| m.start);
                                    for mr in ms {
                                        if mr.start < last { continue; }
                                        if mr.start > last {
                                            spans.push(Span::raw(lm.line_content[last..mr.start].to_string()));
                                        }
                                        let orig = &lm.line_content[mr.start..mr.end];
                                        spans.push(Span::styled(orig.to_string(), Style::default().fg(Color::White).bg(Color::Red).add_modifier(Modifier::CROSSED_OUT)));
                                        let repl = match replace_mode {
                                            ReplaceMode::Simple => replace_text.clone(),
                                            ReplaceMode::PreserveCase => preserve_case(orig, &replace_text),
                                            ReplaceMode::DeleteLine => String::new(),
                                        };
                                        spans.push(Span::styled(repl, Style::default().fg(Color::White).bg(Color::Green)));
                                        last = mr.end;
                                    }
                                    if last < lm.line_content.len() {
                                        spans.push(Span::raw(lm.line_content[last..].to_string()));
                                    }
                                } else if replace_mode == ReplaceMode::DeleteLine {
                                    spans.push(Span::styled(lm.line_content.clone(), Style::default().fg(Color::Red).add_modifier(Modifier::CROSSED_OUT)));
                                } else {
                                    let mut last = 0;
                                    let mut ms = lm.matches.clone();
                                    ms.sort_by_key(|m| m.start);
                                    for mr in ms {
                                        if mr.start < last { continue; }
                                        if mr.start > last {
                                            spans.push(Span::raw(lm.line_content[last..mr.start].to_string()));
                                        }
                                        spans.push(Span::styled(lm.line_content[mr.start..mr.end].to_string(), Style::default().bg(Color::Yellow).fg(Color::Black)));
                                        last = mr.end;
                                    }
                                    if last < lm.line_content.len() {
                                        spans.push(Span::raw(lm.line_content[last..].to_string()));
                                    }
                                }
                                // Highlight selected line bg?
                                let style = if is_selected { Style::default().bg(Color::DarkGray) } else { Style::default() };
                                let mut line = Line::from(spans);
                                for span in line.spans.iter_mut() {
                                    span.style = span.style.patch(style);
                                }
                                preview_lines.push(line);
                            }
                        }
                    }
                }
            }
            let preview_para = Paragraph::new(preview_lines).block(Block::default())
                .wrap(Wrap { trim: false });
            f.render_widget(preview_para, inner_preview);

            // Help line at bottom
            let help_text = if confirm_dialog.is_some() {
                "Confirm Replace: <Enter> | Cancel Replace: <Esc>, Left: <h>, Right: <l>, Loop: <Tab>"
            } else if show_help {
                "Close Help: <Esc> | Next Tab: <Right> | Previous Tab: <Left>"
            } else {
                match focus {
                    Focus::Search => "Help: <Ctrl-b> | Search: <Enter> | Toggle search mode: <Ctrl-n>",
                    Focus::Replace => "Help: <Ctrl-b> | Replace: <C-o> | Toggle replace mode: <Ctrl-n>",
                    Focus::ResultList => {
                        if result_state == ResultListState::FileList {
                            "Help: <Ctrl-b> | Open File: <Enter> | Replace File: <r> | Next: <j> | Previous: <k> | Top: <g> | Bottom: <G> | Delete file: <d>"
                        } else {
                            "Help: <Ctrl-b> | Back to list: <Enter> | Replace Line: <r> | Next: <j> | Previous: <k> | Top: <g> | Bottom: <G> | Delete line: <d>"
                        }
                    }
                }
            };
            let help_para = Paragraph::new(help_text);
            f.render_widget(help_para, bottom_help_area);

            // Help dialog overlay
            if show_help {
                let help_area = centered_rect(70, 60, area);
                f.render_widget(Clear, help_area);
                let block = Block::default().borders(Borders::ALL).title(format!(" [{}] Global ─ [{}] Navigation ──────────────────────────────Press 'q' to close", if help_tab==0 { "1" } else { "1" }, if help_tab==1 { "2" } else { "2" }));
                f.render_widget(block.clone(), help_area);
                let inner = block.inner(help_area);
                let help_content = if help_tab == 0 {
                    vec![
                        Line::from(""),
                        Line::from(" - Ctrl-c: Quit"),
                        Line::from(" - Ctrl-d: Quit"),
                        Line::from(" - Ctrl-b: Help dialog"),
                        Line::from(" - Ctrl-o: Process Replace For All Files"),
                        Line::from(" - Ctrl-n: Loop through search and replace modes"),
                        Line::from(" - Enter: Select/Deselect file"),
                        Line::from(" - d: delete file/delete line from the replace process"),
                        Line::from(" - r: Replace Selected File Or Line"),
                    ]
                } else {
                    vec![
                        Line::from(""),
                        Line::from(" - Tab: Loop through panes"),
                        Line::from(" - j/UpArrow: Move up"),
                        Line::from(" - k/DownArrow: Move down"),
                        Line::from(" - h/g/LeftArrow: Move to Top"),
                        Line::from(" - l/G/RightArrow: Move to Bottom"),
                    ]
                };
                let para = Paragraph::new(help_content);
                f.render_widget(para, inner);
            }

            // Confirm dialog overlay
            if let Some(selected) = confirm_dialog {
                let confirm_area = centered_rect(50, 20, area);
                f.render_widget(Clear, confirm_area);
                let block = Block::default().borders(Borders::ALL).title("Confirm Dialog");
                f.render_widget(block.clone(), confirm_area);
                let inner = block.inner(confirm_area);
                let inner_layout = Layout::default()
                    .direction(Direction::Vertical)
                    .constraints([Constraint::Min(0), Constraint::Length(3)])
                    .split(inner);
                let msg_area = inner_layout[0];
                let buttons_area = inner_layout[1];

                let msg = vec![
                    Line::from(""),
                    Line::from(" This action will modify the files in this directory. "),
                    Line::from("          Are you sure you want to continue?          "),
                    Line::from(""),
                ];
                let msg_para = Paragraph::new(msg).alignment(Alignment::Center);
                f.render_widget(msg_para, msg_area);

                let buttons_layout = Layout::default()
                    .direction(Direction::Horizontal)
                    .constraints([Constraint::Percentage(50), Constraint::Percentage(50)])
                    .split(buttons_area);
                let cancel_style = if selected == 0 { Style::default().bg(Color::Blue).fg(Color::White) } else { Style::default() };
                let confirm_style = if selected == 1 { Style::default().bg(Color::Blue).fg(Color::White) } else { Style::default() };
                let cancel_para = Paragraph::new("Cancel").style(cancel_style).alignment(Alignment::Center).block(Block::default().borders(Borders::ALL));
                let confirm_para = Paragraph::new("Confirm").style(confirm_style).alignment(Alignment::Center).block(Block::default().borders(Borders::ALL));
                f.render_widget(cancel_para, buttons_layout[0]);
                f.render_widget(confirm_para, buttons_layout[1]);
            }

            // Notification overlay at bottom right of preview
            if let Some((msg, _)) = &notification {
                let notif_area = Rect {
                    x: area.width - (msg.len() as u16 + 6),
                    y: area.height - 5,
                    width: msg.len() as u16 + 4,
                    height: 3,
                };
                f.render_widget(Clear, notif_area);
                let block = Block::default().borders(Borders::ALL).title("Notification");
                let para = Paragraph::new(msg.as_str()).block(block);
                f.render_widget(para, notif_area);
            }
        })?;

        // Check notification timeout
        if let Some((_, instant)) = &notification {
            if instant.elapsed().as_secs() > 3 {
                notification = None;
            }
        }

        if event::poll(std::time::Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                // Handle confirm dialog first
                if let Some(selected) = confirm_dialog {
                    match key.code {
                        KeyCode::Esc => {
                            confirm_dialog = None;
                        }
                        KeyCode::Enter => {
                            if selected == 1 {
                                // Perform replace all
                                perform_replace_all(&project_root, &search_results, &search_text, &replace_text, search_mode, replace_mode, &deleted_files, &deleted_lines);
                                notification = Some(("Search and replace completed successfully".to_string(), std::time::Instant::now()));
                                // Re-search
                                search_results = search_files(&project_root, &search_text, search_mode);
                                // Reset deletions
                                deleted_files.clear();
                                deleted_lines.clear();
                                file_selected = 0;
                                opened_file = None;
                                result_state = ResultListState::FileList;
                            }
                            confirm_dialog = None;
                        }
                        KeyCode::Char('h') | KeyCode::Left => {
                            confirm_dialog = Some(0);
                        }
                        KeyCode::Char('l') | KeyCode::Right => {
                            confirm_dialog = Some(1);
                        }
                        KeyCode::Tab | KeyCode::BackTab => {
                            confirm_dialog = Some(if selected == 0 { 1 } else { 0 });
                        }
                        _ => {}
                    }
                    continue;
                }

                // Help dialog
                if show_help {
                    match key.code {
                        KeyCode::Char('q') | KeyCode::Esc => {
                            show_help = false;
                        }
                        KeyCode::Right => {
                            help_tab = (help_tab + 1) % 2;
                        }
                        KeyCode::Left => {
                            help_tab = (help_tab + 1) % 2; // only 2 tabs, same as right
                            if help_tab == 0 { help_tab = 1; } else { help_tab = 0; }
                            // Actually toggle
                            help_tab = 1 - help_tab;
                        }
                        _ => {}
                    }
                    continue;
                }

                // Global keybindings from config?
                // For simplicity, hardcoded
                if key.modifiers.contains(KeyModifiers::CONTROL) {
                    match key.code {
                        KeyCode::Char('c') | KeyCode::Char('d') => {
                            break;
                        }
                        KeyCode::Char('z') => {
                            // Suspend
                            // Restore terminal
                            terminal::disable_raw_mode()?;
                            execute!(terminal.backend_mut(), terminal::LeaveAlternateScreen, event::DisableMouseCapture)?;
                            // Safety: send SIGTSTP
                            unsafe { libc::raise(libc::SIGTSTP); }
                            // After resume, re-enable
                            terminal::enable_raw_mode()?;
                            execute!(terminal.backend_mut(), terminal::EnterAlternateScreen, event::EnableMouseCapture)?;
                            terminal.clear()?;
                        }
                        KeyCode::Char('r') => {
                            // Refresh: re-search
                            search_results = search_files(&project_root, &search_text, search_mode);
                            file_selected = 0;
                        }
                        KeyCode::Char('o') => {
                            if !search_results.is_empty() {
                                confirm_dialog = Some(0); // start with Cancel selected
                            }
                        }
                        KeyCode::Char('b') => {
                            show_help = true;
                            help_tab = 0;
                        }
                        KeyCode::Char('n') => {
                            match focus {
                                Focus::Search => {
                                    search_mode = search_mode.next();
                                }
                                Focus::Replace => {
                                    replace_mode = replace_mode.next();
                                }
                                _ => {}
                            }
                        }
                        _ => {}
                    }
                    continue;
                }

                match focus {
                    Focus::Search => {
                        match key.code {
                            KeyCode::Enter => {
                                search_results = search_files(&project_root, &search_text, search_mode);
                                file_selected = 0;
                                opened_file = None;
                                result_state = ResultListState::FileList;
                                deleted_files.clear();
                                deleted_lines.clear();
                            }
                            KeyCode::Tab => {
                                focus = Focus::Replace;
                            }
                            KeyCode::BackTab => {
                                focus = Focus::ResultList;
                            }
                            KeyCode::Char(c) => {
                                search_text.insert(search_cursor, c);
                                search_cursor += 1;
                            }
                            KeyCode::Backspace => {
                                if search_cursor > 0 {
                                    search_cursor -= 1;
                                    search_text.remove(search_cursor);
                                }
                            }
                            KeyCode::Delete => {
                                if search_cursor < search_text.len() {
                                    search_text.remove(search_cursor);
                                }
                            }
                            KeyCode::Left => {
                                if search_cursor > 0 { search_cursor -= 1; }
                            }
                            KeyCode::Right => {
                                if search_cursor < search_text.len() { search_cursor += 1; }
                            }
                            KeyCode::Esc => {
                                // clear?
                            }
                            KeyCode::Char('u') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                                search_text.clear();
                                search_cursor = 0;
                            }
                            _ => {}
                        }
                    }
                    Focus::Replace => {
                        match key.code {
                            KeyCode::Tab => {
                                focus = Focus::ResultList;
                            }
                            KeyCode::BackTab => {
                                focus = Focus::Search;
                            }
                            KeyCode::Char(c) => {
                                if replace_mode != ReplaceMode::DeleteLine {
                                    replace_text.insert(replace_cursor, c);
                                    replace_cursor += 1;
                                }
                            }
                            KeyCode::Backspace => {
                                if replace_mode != ReplaceMode::DeleteLine && replace_cursor > 0 {
                                    replace_cursor -= 1;
                                    replace_text.remove(replace_cursor);
                                }
                            }
                            KeyCode::Delete => {
                                if replace_mode != ReplaceMode::DeleteLine && replace_cursor < replace_text.len() {
                                    replace_text.remove(replace_cursor);
                                }
                            }
                            KeyCode::Left => {
                                if replace_cursor > 0 { replace_cursor -= 1; }
                            }
                            KeyCode::Right => {
                                if replace_cursor < replace_text.len() { replace_cursor += 1; }
                            }
                            KeyCode::Char('u') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                                if replace_mode != ReplaceMode::DeleteLine {
                                    replace_text.clear();
                                    replace_cursor = 0;
                                }
                            }
                            _ => {}
                        }
                    }
                    Focus::ResultList => {
                        match result_state {
                            ResultListState::FileList => {
                                match key.code {
                                    KeyCode::Tab => {
                                        focus = Focus::Search;
                                    }
                                    KeyCode::BackTab => {
                                        focus = Focus::Replace;
                                    }
                                    KeyCode::Char('j') | KeyCode::Down => {
                                        if file_selected + 1 < search_results.len() {
                                            // find next not deleted
                                            let mut next = file_selected + 1;
                                            while next < search_results.len() && deleted_files.contains(&next) {
                                                next += 1;
                                            }
                                            if next < search_results.len() {
                                                file_selected = next;
                                            }
                                        }
                                    }
                                    KeyCode::Char('k') | KeyCode::Up => {
                                        if file_selected > 0 {
                                            let mut prev = file_selected - 1;
                                            loop {
                                                if !deleted_files.contains(&prev) { break; }
                                                if prev == 0 { break; }
                                                prev -= 1;
                                            }
                                            if !deleted_files.contains(&prev) {
                                                file_selected = prev;
                                            }
                                        }
                                    }
                                    KeyCode::Char('g') | KeyCode::Char('h') | KeyCode::Left => {
                                        // Top
                                        file_selected = 0;
                                        while file_selected < search_results.len() && deleted_files.contains(&file_selected) {
                                            file_selected += 1;
                                        }
                                    }
                                    KeyCode::Char('G') | KeyCode::Char('l') | KeyCode::Right => {
                                        // Bottom
                                        file_selected = search_results.len().saturating_sub(1);
                                        while file_selected > 0 && deleted_files.contains(&file_selected) {
                                            file_selected -= 1;
                                        }
                                    }
                                    KeyCode::Enter => {
                                        if !search_results.is_empty() && file_selected < search_results.len() {
                                            opened_file = Some(file_selected);
                                            result_state = ResultListState::LineList;
                                            line_selected = 0;
                                        }
                                    }
                                    KeyCode::Char('r') => {
                                        // Replace file
                                        if file_selected < search_results.len() && !deleted_files.contains(&file_selected) {
                                            let fr = &search_results[file_selected];
                                            perform_replace_file(fr, &search_text, &replace_text, search_mode, replace_mode, &deleted_lines.get(&file_selected).cloned().unwrap_or_default());
                                            notification = Some(("File replacement completed successfully".to_string(), std::time::Instant::now()));
                                            search_results = search_files(&project_root, &search_text, search_mode);
                                            deleted_files.clear();
                                            deleted_lines.clear();
                                            file_selected = 0;
                                        }
                                    }
                                    KeyCode::Char('d') => {
                                        if file_selected < search_results.len() {
                                            deleted_files.insert(file_selected);
                                            // Move selection
                                            // Find next valid
                                            let mut next = file_selected;
                                            while next < search_results.len() && deleted_files.contains(&next) {
                                                next += 1;
                                            }
                                            if next < search_results.len() {
                                                file_selected = next;
                                            } else {
                                                // try previous
                                                if file_selected > 0 {
                                                    let mut prev = file_selected - 1;
                                                    while prev > 0 && deleted_files.contains(&prev) {
                                                        prev -= 1;
                                                    }
                                                    file_selected = prev;
                                                }
                                            }
                                        }
                                    }
                                    _ => {}
                                }
                            }
                            ResultListState::LineList => {
                                match key.code {
                                    KeyCode::Enter => {
                                        result_state = ResultListState::FileList;
                                    }
                                    KeyCode::Tab => {
                                        // Loop? In original, Tab loops over panes even in line list? Likely still loops
                                        focus = Focus::Search;
                                        result_state = ResultListState::FileList;
                                    }
                                    KeyCode::BackTab => {
                                        focus = Focus::Replace;
                                        result_state = ResultListState::FileList;
                                    }
                                    KeyCode::Char('j') | KeyCode::Down => {
                                        if let Some(open_idx) = opened_file {
                                            if open_idx < search_results.len() {
                                                let fr = &search_results[open_idx];
                                                let deleted_set = deleted_lines.get(&open_idx);
                                                let filtered_count = fr.line_matches.iter().filter(|lm| {
                                                    if let Some(set) = deleted_set {
                                                        !set.contains(&lm.line_number)
                                                    } else { true }
                                                }).count();
                                                if line_selected + 1 < filtered_count {
                                                    line_selected += 1;
                                                }
                                            }
                                        }
                                    }
                                    KeyCode::Char('k') | KeyCode::Up => {
                                        if line_selected > 0 {
                                            line_selected -= 1;
                                        }
                                    }
                                    KeyCode::Char('g') | KeyCode::Char('h') | KeyCode::Left => {
                                        line_selected = 0;
                                    }
                                    KeyCode::Char('G') | KeyCode::Char('l') | KeyCode::Right => {
                                        if let Some(open_idx) = opened_file {
                                            if open_idx < search_results.len() {
                                                let fr = &search_results[open_idx];
                                                let deleted_set = deleted_lines.get(&open_idx);
                                                let filtered_count = fr.line_matches.iter().filter(|lm| {
                                                    if let Some(set) = deleted_set {
                                                        !set.contains(&lm.line_number)
                                                    } else { true }
                                                }).count();
                                                if filtered_count > 0 {
                                                    line_selected = filtered_count - 1;
                                                }
                                            }
                                        }
                                    }
                                    KeyCode::Char('r') => {
                                        // Replace line
                                        if let Some(open_idx) = opened_file {
                                            if open_idx < search_results.len() {
                                                let fr = &search_results[open_idx];
                                                let deleted_set = deleted_lines.get(&open_idx);
                                                let filtered: Vec<&LineMatch> = fr.line_matches.iter().filter(|lm| {
                                                    if let Some(set) = deleted_set {
                                                        !set.contains(&lm.line_number)
                                                    } else { true }
                                                }).collect();
                                                if line_selected < filtered.len() {
                                                    let lm = filtered[line_selected];
                                                    perform_replace_line(fr, lm, &search_text, &replace_text, search_mode, replace_mode);
                                                    notification = Some(("Line replacement completed successfully".to_string(), std::time::Instant::now()));
                                                    search_results = search_files(&project_root, &search_text, search_mode);
                                                    // After replace, stay in file list?
                                                    result_state = ResultListState::FileList;
                                                    deleted_files.clear();
                                                    deleted_lines.clear();
                                                    file_selected = 0;
                                                    opened_file = None;
                                                }
                                            }
                                        }
                                    }
                                    KeyCode::Char('d') => {
                                        // Delete line from replace process
                                        if let Some(open_idx) = opened_file {
                                            if open_idx < search_results.len() {
                                                let fr = &search_results[open_idx];
                                                let deleted_set = deleted_lines.get(&open_idx);
                                                let filtered: Vec<&LineMatch> = fr.line_matches.iter().filter(|lm| {
                                                    if let Some(set) = deleted_set {
                                                        !set.contains(&lm.line_number)
                                                    } else { true }
                                                }).collect();
                                                if line_selected < filtered.len() {
                                                    let lm = filtered[line_selected];
                                                    let entry = deleted_lines.entry(open_idx).or_insert_with(HashSet::new);
                                                    entry.insert(lm.line_number);
                                                    // Adjust line_selected if needed
                                                    let new_filtered_count = fr.line_matches.iter().filter(|lm2| {
                                                        if let Some(set) = deleted_lines.get(&open_idx) {
                                                            !set.contains(&lm2.line_number)
                                                        } else { true }
                                                    }).count();
                                                    if line_selected >= new_filtered_count && new_filtered_count > 0 {
                                                        line_selected = new_filtered_count - 1;
                                                    }
                                                    if new_filtered_count == 0 {
                                                        // No more lines in file, delete file?
                                                        deleted_files.insert(open_idx);
                                                        result_state = ResultListState::FileList;
                                                        opened_file = None;
                                                    }
                                                }
                                            }
                                        }
                                    }
                                    _ => {}
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    terminal::disable_raw_mode()?;
    execute!(terminal.backend_mut(), terminal::LeaveAlternateScreen, event::DisableMouseCapture)?;
    Ok(())
}

fn perform_replace_file(fr: &FileResult, search_text: &str, replace_text: &str, search_mode: SearchMode, replace_mode: ReplaceMode, deleted_line_numbers: &HashSet<usize>) {
    if let Ok(content) = fs::read_to_string(&fr.path) {
        let mut new_lines = Vec::new();
        let mut regex_opt: Option<Regex> = None;
        if search_mode == SearchMode::Regex {
            if let Ok(r) = Regex::new(search_text) {
                regex_opt = Some(r);
            }
        }
        for (idx, line) in content.lines().enumerate() {
            if deleted_line_numbers.contains(&idx) {
                new_lines.push(line.to_string());
                continue;
            }
            // Find if line has matches
            let matches = match search_mode {
                SearchMode::Simple => find_matches_simple(line, search_text, false, false),
                SearchMode::MatchCase => find_matches_simple(line, search_text, true, false),
                SearchMode::MatchWholeWord => find_matches_simple(line, search_text, false, true),
                SearchMode::MatchCaseWholeWord => find_matches_simple(line, search_text, true, true),
                SearchMode::Regex => {
                    if let Some(ref re) = regex_opt {
                        find_matches_regex(line, re)
                    } else { vec![] }
                }
            };
            if matches.is_empty() {
                new_lines.push(line.to_string());
            } else {
                if replace_mode == ReplaceMode::DeleteLine {
                    // skip line
                    continue;
                } else {
                    let new_line = replace_line_content(line, &matches, replace_text, replace_mode);
                    new_lines.push(new_line);
                }
            }
        }
        // Preserve final newline?
        let final_content = if content.ends_with('\n') {
            new_lines.join("\n") + "\n"
        } else {
            new_lines.join("\n")
        };
        let _ = fs::write(&fr.path, final_content);
    }
}

fn perform_replace_line(fr: &FileResult, lm: &LineMatch, search_text: &str, replace_text: &str, search_mode: SearchMode, replace_mode: ReplaceMode) {
    if let Ok(content) = fs::read_to_string(&fr.path) {
        let mut new_lines = Vec::new();
        let mut regex_opt: Option<Regex> = None;
        if search_mode == SearchMode::Regex {
            if let Ok(r) = Regex::new(search_text) {
                regex_opt = Some(r);
            }
        }
        for (idx, line) in content.lines().enumerate() {
            if idx == lm.line_number {
                if replace_mode == ReplaceMode::DeleteLine {
                    continue;
                } else {
                    let matches = match search_mode {
                        SearchMode::Simple => find_matches_simple(line, search_text, false, false),
                        SearchMode::MatchCase => find_matches_simple(line, search_text, true, false),
                        SearchMode::MatchWholeWord => find_matches_simple(line, search_text, false, true),
                        SearchMode::MatchCaseWholeWord => find_matches_simple(line, search_text, true, true),
                        SearchMode::Regex => {
                            if let Some(ref re) = regex_opt {
                                find_matches_regex(line, re)
                            } else { vec![] }
                        }
                    };
                    let new_line = replace_line_content(line, &matches, replace_text, replace_mode);
                    new_lines.push(new_line);
                }
            } else {
                new_lines.push(line.to_string());
            }
        }
        let final_content = if content.ends_with('\n') {
            new_lines.join("\n") + "\n"
        } else {
            new_lines.join("\n")
        };
        let _ = fs::write(&fr.path, final_content);
    }
}

