#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SearchMode {
    Simple,
    MatchCase,
    MatchWholeWord,
    MatchCaseWholeWord,
    Regex,
}
impl SearchMode {
    fn as_str(&self) -> &'static str {
        match self {
            Self::Simple => "Simple",
            Self::MatchCase => "Match Case",
            Self::MatchWholeWord => "Match Whole Word",
            Self::MatchCaseWholeWord => "Match Case Whole Word",
            Self::Regex => "Regex",
        }
    }
    fn next(&self) -> Self {
        match self {
            Self::Simple => Self::MatchCase,
            Self::MatchCase => Self::MatchWholeWord,
            Self::MatchWholeWord => Self::MatchCaseWholeWord,
            Self::MatchCaseWholeWord => Self::Regex,
            Self::Regex => Self::Simple,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ReplaceMode {
    Simple,
    PreserveCase,
    DeleteLine,
}
impl ReplaceMode {
    fn as_str(&self) -> &'static str {
        match self {
            Self::Simple => "Simple",
            Self::PreserveCase => "Preserve Case",
            Self::DeleteLine => "Delete Line",
        }
    }
    fn next(&self) -> Self {
        match self {
            Self::Simple => Self::PreserveCase,
            Self::PreserveCase => Self::DeleteLine,
            Self::DeleteLine => Self::Simple,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Focus {
    Search,
    Replace,
    ResultList,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ResultListState {
    FileList,
    LineList,
