#[derive(Debug, Clone)]
struct MatchRange {
    start: usize,
    end: usize,
}
#[derive(Debug, Clone)]
struct LineMatch {
    line_number: usize,
    line_content: String,
    matches: Vec<MatchRange>,
}
#[derive(Debug, Clone)]
struct FileResult {
    path: PathBuf,
    rel_path: String,
    line_matches: Vec<LineMatch>,
    total_matches: usize,
