#[derive(Debug, Clone)]
struct MatchRange {
    start: usize,
    end: usize,
}
#[derive(Debug, Clone)]
struct LineMatch {
    line_number: usize,
    line_content: String,
    matches: Vec<MatchRange>,
}
#[derive(Debug, Clone)]
struct FileResult {
    path: PathBuf,
    rel_path: String,
    line_matches: Vec<LineMatch>,
    total_matches: usize,
}

fn is_word_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

fn find_matches_simple(line: &str, search: &str, case_sensitive: bool, whole_word: bool) -> Vec<MatchRange> {
    if search.is_empty() {
        return vec![];
    }
    let mut result = Vec::new();
    let search_cmp = if case_sensitive { search.to_string() } else { search.to_lowercase() };
    let line_cmp = if case_sensitive { line.to_string() } else { line.to_lowercase() };
    let mut start = 0;
    while let Some(pos) = line_cmp[start..].find(&search_cmp) {
        let abs_start = start + pos;
        let abs_end = abs_start + search_cmp.len();
        if abs_end <= line.len() {
            if whole_word {
                let before_ok = if abs_start == 0 {
                    true
                } else {
                    let prev_char = line[..abs_start].chars().last();
                    if let Some(pc) = prev_char { !is_word_char(pc) } else { true }
                };
                let after_ok = if abs_end >= line.len() {
                    true
                } else {
                    let next_char = line[abs_end..].chars().next();
                    if let Some(nc) = next_char { !is_word_char(nc) } else { true }
                };
                if before_ok && after_ok {
                    result.push(MatchRange { start: abs_start, end: abs_end });
                }
            } else {
                result.push(MatchRange { start: abs_start, end: abs_end });
            }
        }
        start = abs_end;
        if start >= line_cmp.len() { break; }
    }
    result
}

fn find_matches_regex(line: &str, re: &Regex) -> Vec<MatchRange> {
    let mut res = Vec::new();
    for m in re.find_iter(line) {
        res.push(MatchRange { start: m.start(), end: m.end() });
    }
    res
}

fn search_files(project_root: &Path, search_text: &str, mode: SearchMode) -> Vec<FileResult> {
    if search_text.is_empty() { return vec![]; }
    let mut regex_opt: Option<Regex> = None;
    if mode == SearchMode::Regex {
        if let Ok(r) = Regex::new(search_text) { regex_opt = Some(r); } else { return vec![]; }
    }
    let mut results = Vec::new();
    let walker = ignore::WalkBuilder::new(project_root)
        .hidden(true)
        .git_ignore(true)
        .git_global(true)
        .git_exclude(true)
        .ignore(true)
        .build();
    for entry in walker {
        if let Ok(entry) = entry {
            let path = entry.path();
            if path.is_dir() { continue; }
            let mut skip = false;
            for comp in path.components() {
                if let std::path::Component::Normal(os_str) = comp {
                    if let Some(s) = os_str.to_str() {
                        if s.starts_with('.') { skip = true; break; }
                    }
                }
            }
            if skip { continue; }
            let content_bytes = match fs::read(path) { Ok(b) => b, Err(_) => continue, };
            if content_bytes.contains(&0) { continue; }
            let content = match String::from_utf8(content_bytes) { Ok(s) => s, Err(_) => continue, };
            let mut line_matches = Vec::new();
            let mut total = 0;
            for (idx, line) in content.lines().enumerate() {
                let matches = match mode {
                    SearchMode::Simple => find_matches_simple(line, search_text, false, false),
                    SearchMode::MatchCase => find_matches_simple(line, search_text, true, false),
                    SearchMode::MatchWholeWord => find_matches_simple(line, search_text, false, true),
                    SearchMode::MatchCaseWholeWord => find_matches_simple(line, search_text, true, true),
                    SearchMode::Regex => { if let Some(ref re) = regex_opt { find_matches_regex(line, re) } else { vec![] } }
                };
                if !matches.is_empty() {
                    total += matches.len();
                    line_matches.push(LineMatch { line_number: idx, line_content: line.to_string(), matches });
                }
            }
            if total > 0 {
                let rel = path.strip_prefix(project_root).unwrap_or(path).to_string_lossy().to_string();
                results.push(FileResult { path: path.to_path_buf(), rel_path: rel, line_matches, total_matches: total });
            }
        }
    }
    results.sort_by(|a,b| b.rel_path.cmp(&a.rel_path));
    results
}

fn preserve_case(original: &str, replacement: &str) -> String {
    let has_alpha = original.chars().any(|c| c.is_alphabetic());
    if !has_alpha { return replacement.to_string(); }
    let all_upper = original.chars().filter(|c| c.is_alphabetic()).all(|c| c.is_uppercase());
    if all_upper { return replacement.to_uppercase(); }
    if let Some(first) = original.chars().next() {
        if first.is_uppercase() {
            let mut chars = replacement.chars();
            if let Some(f) = chars.next() {
                let mut s = String::new();
                s.push(f.to_uppercase().next().unwrap_or(f));
                for c in chars { s.push(c.to_lowercase().next().unwrap_or(c)); }
                return s;
            } else { return replacement.to_string(); }
        }
    }
    replacement.to_lowercase()
}

fn replace_line_content(line: &str, matches: &[MatchRange], replace_text: &str, mode: ReplaceMode) -> String {
    if mode == ReplaceMode::DeleteLine { return String::new(); }
    if matches.is_empty() { return line.to_string(); }
    let mut sorted = matches.to_vec();
    sorted.sort_by_key(|m| m.start);
    let mut result = String::new();
    let mut last = 0;
    for mr in sorted {
        if mr.start < last { continue; }
        result.push_str(&line[last..mr.start]);
        let original_matched = &line[mr.start..mr.end];
        let repl = match mode {
            ReplaceMode::Simple => replace_text.to_string(),
            ReplaceMode::PreserveCase => preserve_case(original_matched, replace_text),
            ReplaceMode::DeleteLine => String::new(),
        };
        result.push_str(&repl);
        last = mr.end;
    }
    result.push_str(&line[last..]);
    result
}

