                let block = Block::default().border_type(BorderType::Rounded).borders(Borders::ALL).title(format!(" [1] Global ─ [2] Navigation ───────────────────────────────Press 'q' to close"));
                f.render_widget(block.clone(), help_area);
                let inner = block.inner(help_area);
