            Self::MatchCase => "Match Case",
            Self::MatchWholeWord => "Match Whole Word",
            Self::MatchCaseWholeWord => "Match Case Whole Word",
            Self::Regex => "Regex",
        }
    }
    fn next(&self) -> Self {
        match self {
            Self::Simple => Self::MatchCase,
            Self::MatchCase => Self::MatchWholeWord,
            Self::MatchWholeWord => Self::MatchCaseWholeWord,
            Self::MatchCaseWholeWord => Self::Regex,
            Self::Regex => Self::Simple,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ReplaceMode {
    Simple,
    PreserveCase,
    DeleteLine,
}
impl ReplaceMode {
    fn as_str(&self) -> &'static str {
        match self {
            Self::Simple => "Simple",
            Self::PreserveCase => "Preserve Case",
            Self::DeleteLine => "Delete Line",
        }
    }
    fn next(&self) -> Self {
        match self {
            Self::Simple => Self::PreserveCase,
            Self::PreserveCase => Self::DeleteLine,
            Self::DeleteLine => Self::Simple,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Focus {
    Search,
    Replace,
    ResultList,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ResultListState {
    FileList,
    LineList,
}

#[derive(Debug, Clone)]
struct MatchRange {
    start: usize,
    end: usize,
}
#[derive(Debug, Clone)]
struct LineMatch {
    line_number: usize,
    line_content: String,
    matches: Vec<MatchRange>,
}
#[derive(Debug, Clone)]
struct FileResult {
    path: PathBuf,
    rel_path: String,
    line_matches: Vec<LineMatch>,
    total_matches: usize,
}

fn is_word_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

fn find_matches_simple(line: &str, search: &str, case_sensitive: bool, whole_word: bool) -> Vec<MatchRange> {
    if search.is_empty() {
        return vec![];
    }
    let mut result = Vec::new();
    let search_cmp = if case_sensitive { search.to_string() } else { search.to_lowercase() };
    let line_cmp = if case_sensitive { line.to_string() } else { line.to_lowercase() };
    let mut start = 0;
    while let Some(pos) = line_cmp[start..].find(&search_cmp) {
        let abs_start = start + pos;
        let abs_end = abs_start + search_cmp.len();
        if abs_end <= line.len() {
            if whole_word {
                let before_ok = if abs_start == 0 {
                    true
                } else {
                    let prev_char = line[..abs_start].chars().last();
                    if let Some(pc) = prev_char { !is_word_char(pc) } else { true }
                };
                let after_ok = if abs_end >= line.len() {
                    true
                } else {
                    let next_char = line[abs_end..].chars().next();
                    if let Some(nc) = next_char { !is_word_char(nc) } else { true }
                };
                if before_ok && after_ok {
                    result.push(MatchRange { start: abs_start, end: abs_end });
                }
            } else {
                result.push(MatchRange { start: abs_start, end: abs_end });
            }
        }
        start = abs_end;
        if start >= line_cmp.len() { break; }
    }
    result
}

fn find_matches_regex(line: &str, re: &Regex) -> Vec<MatchRange> {
    let mut res = Vec::new();
    for m in re.find_iter(line) {
        res.push(MatchRange { start: m.start(), end: m.end() });
    }
    res
}

fn search_files(project_root: &Path, search_text: &str, mode: SearchMode) -> Vec<FileResult> {
    if search_text.is_empty() { return vec![]; }
    let mut regex_opt: Option<Regex> = None;
    if mode == SearchMode::Regex {
        if let Ok(r) = Regex::new(search_text) { regex_opt = Some(r); } else { return vec![]; }
    }
    let mut results = Vec::new();
    let walker = ignore::WalkBuilder::new(project_root)
        .hidden(true)
        .git_ignore(true)
        .git_global(true)
        .git_exclude(true)
        .ignore(true)
        .build();
    for entry in walker {
        if let Ok(entry) = entry {
            let path = entry.path();
            if path.is_dir() { continue; }
            let mut skip = false;
            for comp in path.components() {
                if let std::path::Component::Normal(os_str) = comp {
                    if let Some(s) = os_str.to_str() {
                        if s.starts_with('.') { skip = true; break; }
                    }
                }
            }
            if skip { continue; }
            let content_bytes = match fs::read(path) { Ok(b) => b, Err(_) => continue, };
            if content_bytes.contains(&0) { continue; }
            let content = match String::from_utf8(content_bytes) { Ok(s) => s, Err(_) => continue, };
            let mut line_matches = Vec::new();
            let mut total = 0;
            for (idx, line) in content.lines().enumerate() {
                let matches = match mode {
                    SearchMode::Simple => find_matches_simple(line, search_text, false, false),
                    SearchMode::MatchCase => find_matches_simple(line, search_text, true, false),
                    SearchMode::MatchWholeWord => find_matches_simple(line, search_text, false, true),
                    SearchMode::MatchCaseWholeWord => find_matches_simple(line, search_text, true, true),
                    SearchMode::Regex => { if let Some(ref re) = regex_opt { find_matches_regex(line, re) } else { vec![] } }
                };
                if !matches.is_empty() {
                    total += matches.len();
                    line_matches.push(LineMatch { line_number: idx, line_content: line.to_string(), matches });
                }
            }
            if total > 0 {
                let rel = path.strip_prefix(project_root).unwrap_or(path).to_string_lossy().to_string();
                results.push(FileResult { path: path.to_path_buf(), rel_path: rel, line_matches, total_matches: total });
            }
        }
    }
    results.sort_by(|a,b| b.rel_path.cmp(&a.rel_path));
    results
}

fn preserve_case(original: &str, replacement: &str) -> String {
    let has_alpha = original.chars().any(|c| c.is_alphabetic());
    if !has_alpha { return replacement.to_string(); }
    let all_upper = original.chars().filter(|c| c.is_alphabetic()).all(|c| c.is_uppercase());
    if all_upper { return replacement.to_uppercase(); }
    if let Some(first) = original.chars().next() {
        if first.is_uppercase() {
            let mut chars = replacement.chars();
            if let Some(f) = chars.next() {
                let mut s = String::new();
                s.push(f.to_uppercase().next().unwrap_or(f));
                for c in chars { s.push(c.to_lowercase().next().unwrap_or(c)); }
                return s;
            } else { return replacement.to_string(); }
        }
    }
    replacement.to_lowercase()
}

fn replace_line_content(line: &str, matches: &[MatchRange], replace_text: &str, mode: ReplaceMode) -> String {
    if mode == ReplaceMode::DeleteLine { return String::new(); }
    if matches.is_empty() { return line.to_string(); }
    let mut sorted = matches.to_vec();
    sorted.sort_by_key(|m| m.start);
    let mut result = String::new();
    let mut last = 0;
    for mr in sorted {
        if mr.start < last { continue; }
        result.push_str(&line[last..mr.start]);
        let original_matched = &line[mr.start..mr.end];
        let repl = match mode {
            ReplaceMode::Simple => replace_text.to_string(),
            ReplaceMode::PreserveCase => preserve_case(original_matched, replace_text),
            ReplaceMode::DeleteLine => String::new(),
        };
        result.push_str(&repl);
        last = mr.end;
    }
    result.push_str(&line[last..]);
    result
}

fn config_dir() -> PathBuf {
    if let Some(xdg) = std::env::var_os("XDG_CONFIG_HOME") { PathBuf::from(xdg).join("serpl") }
    else if let Some(home) = std::env::var_os("HOME") { PathBuf::from(home).join(".config").join("serpl") }
    else { PathBuf::from("/home/agent/.config/serpl") }
}

#[derive(Debug, Deserialize)]
struct Config { keybindings: Option<HashMap<String, String>>, }

fn load_config() -> Option<Config> {
    let cfg_path = config_dir().join("config.json5");
    if let Ok(content) = fs::read_to_string(&cfg_path) {
        if let Ok(cfg) = serde_json::from_str::<Config>(&content) { return Some(cfg); }
    }
    let alt = PathBuf::from(".config/config.json5");
    if let Ok(content) = fs::read_to_string(&alt) {
        if let Ok(cfg) = serde_json::from_str::<Config>(&content) { return Some(cfg); }
    }
    None
}

fn main() -> io::Result<()> {
    let args: Vec<String> = std::env::args().collect();
    let mut project_root_str = ".".to_string();
    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];
        if arg == "-h" || arg == "--help" {
            println!("A simple terminal UI for search and replace, ala VS Code\n\nUsage: executable [OPTIONS]\n\nOptions:\n  -p, --project-root <PATH>  Path to the project root [default: .]\n  -h, --help                 Print help\n  -V, --version              Print version");
            return Ok(());
        } else if arg == "-V" || arg == "--version" {
            println!("serpl 0.3.4- (2026-08-10)\n\nAuthors: Yassine Bridi <ybridi@gmail.com>\n\nConfig directory: {}", config_dir().display());
            return Ok(());
        } else if arg == "-p" || arg == "--project-root" {
            if i + 1 < args.len() { project_root_str = args[i+1].clone(); i += 1; }
        } else if arg.starts_with("--project-root=") {
            project_root_str = arg.splitn(2,'=').nth(1).unwrap_or(".").to_string();
        }
        i += 1;
    }
    let project_root = PathBuf::from(&project_root_str);
    let project_root = if project_root.exists() { project_root } else { PathBuf::from(".") };

    terminal::enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, terminal::EnterAlternateScreen, event::EnableMouseCapture)?;
    let backend = ratatui::backend::CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let mut search_text = String::new();
    let mut replace_text = String::new();
    let mut search_mode = SearchMode::Simple;
    let mut replace_mode = ReplaceMode::Simple;
    let mut focus = Focus::Search;
    let mut result_state = ResultListState::FileList;
    let mut search_results: Vec<FileResult> = Vec::new();
    let mut file_selected: Option<usize> = None;
    let mut line_selected: usize = 0;
    let mut opened_file: Option<usize> = None;
    let mut deleted_files: HashSet<usize> = HashSet::new();
    let mut deleted_lines: HashMap<usize, HashSet<usize>> = HashMap::new();
    let mut show_help = false;
    let mut help_tab = 0;
    let mut confirm_dialog: Option<usize> = None;
    let mut notification: Option<(String, std::time::Instant)> = None;
    let mut search_cursor = 0usize;
    let mut replace_cursor = 0usize;

    let _config = load_config();

    loop {
        terminal.draw(|f| {
            let area = f.area();
            let main_vert = Layout::default().direction(Direction::Vertical).constraints([Constraint::Min(0), Constraint::Length(1)]).split(area);
            let top_area = main_vert[0];
            let bottom_help_area = main_vert[1];
            let horiz_top = Layout::default().direction(Direction::Horizontal).constraints([Constraint::Percentage(35), Constraint::Percentage(65)]).split(top_area);
            let left_top = horiz_top[0];
            let right_top = horiz_top[1];
            let left_vert_top = Layout::default().direction(Direction::Vertical).constraints([Constraint::Length(3), Constraint::Length(3), Constraint::Min(0)]).split(left_top);
            let search_area2 = left_vert_top[0];
            let replace_area2 = left_vert_top[1];
            let result_area2 = left_vert_top[2];

            let search_title = format!("Search [{}]", search_mode.as_str());
            let search_block = Block::default().border_type(BorderType::Rounded).borders(Borders::ALL).border_style(if focus == Focus::Search && !show_help && confirm_dialog.is_none() { Style::default().fg(Color::Green).add_modifier(Modifier::BOLD) } else { Style::default() }).title(search_title);
            let search_para = Paragraph::new(search_text.as_str()).block(search_block);
            f.render_widget(search_para, search_area2);

            let replace_title = format!("Replace [{}]", replace_mode.as_str());
            let replace_block = Block::default().border_type(BorderType::Rounded).borders(Borders::ALL).border_style(if focus == Focus::Replace && !show_help && confirm_dialog.is_none() { Style::default().fg(Color::Green).add_modifier(Modifier::BOLD) } else { Style::default() }).title(replace_title);
            let replace_content = if replace_mode == ReplaceMode::DeleteLine { "[Entire line will be deleted]".to_string() } else { replace_text.clone() };
            let replace_para = Paragraph::new(replace_content).block(replace_block);
            f.render_widget(replace_para, replace_area2);

            let result_block = Block::default().border_type(BorderType::Rounded).borders(Borders::ALL).border_style(if focus == Focus::ResultList && !show_help && confirm_dialog.is_none() { Style::default().fg(Color::Green).add_modifier(Modifier::BOLD) } else { Style::default() }).title("Result List");
            f.render_widget(result_block.clone(), result_area2);
            let inner_result = result_block.inner(result_area2);
            let mut lines = Vec::new();
            // Build visible file indices (not deleted)
            let visible_files: Vec<usize> = (0..search_results.len()).filter(|i| !deleted_files.contains(i)).collect();
            for &idx in &visible_files {
                let fr = &search_results[idx];
                let deleted_set = deleted_lines.get(&idx);
                let remaining_lines: Vec<&LineMatch> = fr.line_matches.iter().filter(|lm| {
                    if let Some(set) = deleted_set { !set.contains(&lm.line_number) } else { true }
                }).collect();
                if remaining_lines.is_empty() && !fr.line_matches.is_empty() { continue; }
                let remaining_count = remaining_lines.iter().map(|lm| lm.matches.len()).sum::<usize>();
                let count_to_show = if deleted_set.is_some() { remaining_count } else { fr.total_matches };
                let display = format!("{} ({})", fr.rel_path, count_to_show);
                let is_selected = if result_state == ResultListState::FileList {
                    if let Some(sel) = file_selected { sel == idx } else { false }
                } else { false };
                let style = if focus == Focus::ResultList && !show_help && confirm_dialog.is_none() && result_state == ResultListState::FileList && is_selected {
                    Style::default().bg(Color::Blue).fg(Color::White)
                } else { Style::default() };
                lines.push(Line::from(Span::styled(display, style)));
            }
            let result_para = Paragraph::new(lines).block(Block::default());
            f.render_widget(result_para, inner_result);

            let preview_block = Block::default().border_type(BorderType::Rounded).borders(Borders::ALL).title("Preview");
            f.render_widget(preview_block.clone(), right_top);
            let inner_preview = preview_block.inner(right_top);
            let mut preview_lines: Vec<Line> = Vec::new();
            if !search_results.is_empty() {
                if result_state == ResultListState::FileList {
                    if let Some(sel_idx) = file_selected {
                        if sel_idx < search_results.len() && !deleted_files.contains(&sel_idx) {
                            let fr = &search_results[sel_idx];
                            let deleted_set = deleted_lines.get(&sel_idx);
                            for lm in &fr.line_matches {
                                if let Some(set) = deleted_set { if set.contains(&lm.line_number) { continue; } }
                                let mut spans = Vec::new();
                                spans.push(Span::raw(format!("   {} ", lm.line_number+1)));
                                if replace_mode != ReplaceMode::DeleteLine && !replace_text.is_empty() {
                                    let mut last = 0;
                                    let mut ms = lm.matches.clone();
                                    ms.sort_by_key(|m| m.start);
                                    for mr in ms {
                                        if mr.start < last { continue; }
                                        if mr.start > last { spans.push(Span::raw(lm.line_content[last..mr.start].to_string())); }
                                        let orig = &lm.line_content[mr.start..mr.end];
                                        spans.push(Span::styled(orig.to_string(), Style::default().fg(Color::White).bg(Color::Red).add_modifier(Modifier::CROSSED_OUT)));
                                        let repl = match replace_mode {
                                            ReplaceMode::Simple => replace_text.clone(),
                                            ReplaceMode::PreserveCase => preserve_case(orig, &replace_text),
                                            ReplaceMode::DeleteLine => String::new(),
                                        };
                                        spans.push(Span::styled(repl, Style::default().fg(Color::White).bg(Color::Green)));
                                        last = mr.end;
                                    }
                                    if last < lm.line_content.len() { spans.push(Span::raw(lm.line_content[last..].to_string())); }
                                } else if replace_mode == ReplaceMode::DeleteLine {
                                    spans.push(Span::styled(lm.line_content.clone(), Style::default().fg(Color::Red).add_modifier(Modifier::CROSSED_OUT)));
                                } else {
                                    let mut last = 0;
                                    let mut ms = lm.matches.clone();
                                    ms.sort_by_key(|m| m.start);
                                    for mr in ms {
                                        if mr.start < last { continue; }
                                        if mr.start > last { spans.push(Span::raw(lm.line_content[last..mr.start].to_string())); }
                                        spans.push(Span::styled(lm.line_content[mr.start..mr.end].to_string(), Style::default().bg(Color::Yellow).fg(Color::Black)));
                                        last = mr.end;
                                    }
                                    if last < lm.line_content.len() { spans.push(Span::raw(lm.line_content[last..].to_string())); }
                                }
                                preview_lines.push(Line::from(spans));
                            }
                        }
                    }
                } else {
                    if let Some(open_idx) = opened_file {
                        if open_idx < search_results.len() {
                            let fr = &search_results[open_idx];
                            let deleted_set = deleted_lines.get(&open_idx);
                            let filtered: Vec<&LineMatch> = fr.line_matches.iter().filter(|lm| {
                                if let Some(set) = deleted_set { !set.contains(&lm.line_number) } else { true }
                            }).collect();
                            for (idx, lm) in filtered.iter().enumerate() {
                                let is_selected = idx == line_selected;
                                let prefix = if is_selected { "> " } else { "  " };
                                let mut spans = Vec::new();
                                spans.push(Span::raw(format!("{}{} ", prefix, lm.line_number+1)));
                                if replace_mode != ReplaceMode::DeleteLine && !replace_text.is_empty() {
                                    let mut last = 0;
                                    let mut ms = lm.matches.clone();
                                    ms.sort_by_key(|m| m.start);
                                    for mr in ms {
                                        if mr.start < last { continue; }
                                        if mr.start > last { spans.push(Span::raw(lm.line_content[last..mr.start].to_string())); }
                                        let orig = &lm.line_content[mr.start..mr.end];
                                        spans.push(Span::styled(orig.to_string(), Style::default().fg(Color::White).bg(Color::Red).add_modifier(Modifier::CROSSED_OUT)));
                                        let repl = match replace_mode {
                                            ReplaceMode::Simple => replace_text.clone(),
                                            ReplaceMode::PreserveCase => preserve_case(orig, &replace_text),
                                            ReplaceMode::DeleteLine => String::new(),
                                        };
                                        spans.push(Span::styled(repl, Style::default().fg(Color::White).bg(Color::Green)));
                                        last = mr.end;
                                    }
                                    if last < lm.line_content.len() { spans.push(Span::raw(lm.line_content[last..].to_string())); }
                                } else if replace_mode == ReplaceMode::DeleteLine {
                                    spans.push(Span::styled(lm.line_content.clone(), Style::default().fg(Color::Red).add_modifier(Modifier::CROSSED_OUT)));
                                } else {
                                    let mut last = 0;
                                    let mut ms = lm.matches.clone();
                                    ms.sort_by_key(|m| m.start);
                                    for mr in ms {
                                        if mr.start < last { continue; }
                                        if mr.start > last { spans.push(Span::raw(lm.line_content[last..mr.start].to_string())); }
                                        spans.push(Span::styled(lm.line_content[mr.start..mr.end].to_string(), Style::default().bg(Color::Yellow).fg(Color::Black)));
                                        last = mr.end;
                                    }
                                    if last < lm.line_content.len() { spans.push(Span::raw(lm.line_content[last..].to_string())); }
                                }
                                let style = if is_selected { Style::default().bg(Color::DarkGray) } else { Style::default() };
                                let mut line = Line::from(spans);
                                for span in line.spans.iter_mut() { span.style = span.style.patch(style); }
                                preview_lines.push(line);
                            }
                        }
                    }
                }
            }
            let preview_para = Paragraph::new(preview_lines).block(Block::default()).wrap(Wrap { trim: false });
            f.render_widget(preview_para, inner_preview);

