                let confirm_style = if selected == 1 { Style::default().bg(Color::Blue).fg(Color::White) } else { Style::default() };
                let cancel_para = Paragraph::new("Cancel").style(cancel_style).alignment(Alignment::Center).block(Block::default().border_type(BorderType::Rounded).borders(Borders::ALL));
                let confirm_para = Paragraph::new("Confirm").style(confirm_style).alignment(Alignment::Center).block(Block::default().border_type(BorderType::Rounded).borders(Borders::ALL));
                f.render_widget(cancel_para, buttons_layout[0]);
                f.render_widget(confirm_para, buttons_layout[1]);
            }

            if let Some((msg, _)) = &notification {
                let notif_area = Rect { x: area.width.saturating_sub(msg.len() as u16 + 6), y: area.height.saturating_sub(5), width: msg.len() as u16 + 4, height: 3 };
                f.render_widget(Clear, notif_area);
                let block = Block::default().border_type(BorderType::Rounded).borders(Borders::ALL).title("Notification");
                let para = Paragraph::new(msg.as_str()).block(block);
                f.render_widget(para, notif_area);
            }
        })?;

        if let Some((_, instant)) = &notification {
            if instant.elapsed().as_secs() > 3 { notification = None; }
        }

        if event::poll(std::time::Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                if let Some(selected) = confirm_dialog {
                    match key.code {
                        KeyCode::Esc => { confirm_dialog = None; }
                        KeyCode::Enter => {
                            if selected == 1 {
                                perform_replace_all(&project_root, &search_results, &search_text, &replace_text, search_mode, replace_mode, &deleted_files, &deleted_lines);
                                notification = Some(("Search and replace completed successfully".to_string(), std::time::Instant::now()));
                                search_results = search_files(&project_root, &search_text, search_mode);
                                deleted_files.clear();
                                deleted_lines.clear();
                                file_selected = None;
                                opened_file = None;
                                result_state = ResultListState::FileList;
                            }
                            confirm_dialog = None;
                        }
                        KeyCode::Char('h') | KeyCode::Left => { confirm_dialog = Some(0); }
                        KeyCode::Char('l') | KeyCode::Right => { confirm_dialog = Some(1); }
                        KeyCode::Tab | KeyCode::BackTab => { confirm_dialog = Some(if selected == 0 { 1 } else { 0 }); }
                        _ => {}
                    }
                    continue;
                }
                if show_help {
                    match key.code {
                        KeyCode::Char('q') | KeyCode::Esc => { show_help = false; }
                        KeyCode::Right => { help_tab = (help_tab + 1) % 2; }
                        KeyCode::Left => { help_tab = 1 - help_tab; }
                        _ => {}
                    }
                    continue;
                }
                if key.modifiers.contains(KeyModifiers::CONTROL) {
                    match key.code {
                        KeyCode::Char('c') | KeyCode::Char('d') => { break; }
                        KeyCode::Char('z') => {
                            terminal::disable_raw_mode()?;
                            execute!(terminal.backend_mut(), terminal::LeaveAlternateScreen, event::DisableMouseCapture)?;
                            unsafe { libc::raise(libc::SIGTSTP); }
                            terminal::enable_raw_mode()?;
                            execute!(terminal.backend_mut(), terminal::EnterAlternateScreen, event::EnableMouseCapture)?;
                            terminal.clear()?;
                        }
                        KeyCode::Char('r') => {
                            search_results = search_files(&project_root, &search_text, search_mode);
                            file_selected = None;
                        }
                        KeyCode::Char('o') => {
                            if !search_results.is_empty() { confirm_dialog = Some(0); }
                        }
                        KeyCode::Char('b') => { show_help = true; help_tab = 0; }
                        KeyCode::Char('n') => {
                            match focus {
                                Focus::Search => { search_mode = search_mode.next(); }
                                Focus::Replace => { replace_mode = replace_mode.next(); }
                                _ => {}
                            }
                        }
                        _ => {}
                    }
                    continue;
                }
                match focus {
                    Focus::Search => {
                        match key.code {
                            KeyCode::Enter => {
                                search_results = search_files(&project_root, &search_text, search_mode);
                                file_selected = None;
                                opened_file = None;
                                result_state = ResultListState::FileList;
                                deleted_files.clear();
                                deleted_lines.clear();
                            }
                            KeyCode::Tab => { focus = Focus::Replace; }
                            KeyCode::BackTab => { focus = Focus::ResultList; }
                            KeyCode::Char(c) => {
                                search_text.insert(search_cursor, c);
                                search_cursor += 1;
                            }
                            KeyCode::Backspace => {
                                if search_cursor > 0 { search_cursor -= 1; search_text.remove(search_cursor); }
                            }
                            KeyCode::Delete => { if search_cursor < search_text.len() { search_text.remove(search_cursor); } }
                            KeyCode::Left => { if search_cursor > 0 { search_cursor -= 1; } }
                            KeyCode::Right => { if search_cursor < search_text.len() { search_cursor += 1; } }
                            _ => {}
                        }
                        if key.modifiers.contains(KeyModifiers::CONTROL) && key.code == KeyCode::Char('u') {
                            search_text.clear();
                            search_cursor = 0;
                        }
                    }
                    Focus::Replace => {
                        match key.code {
                            KeyCode::Tab => { focus = Focus::ResultList; }
                            KeyCode::BackTab => { focus = Focus::Search; }
                            KeyCode::Char(c) => {
                                if replace_mode != ReplaceMode::DeleteLine {
                                    replace_text.insert(replace_cursor, c);
                                    replace_cursor += 1;
                                }
                            }
                            KeyCode::Backspace => {
                                if replace_mode != ReplaceMode::DeleteLine && replace_cursor > 0 {
                                    replace_cursor -= 1;
                                    replace_text.remove(replace_cursor);
                                }
                            }
                            KeyCode::Delete => {
                                if replace_mode != ReplaceMode::DeleteLine && replace_cursor < replace_text.len() { replace_text.remove(replace_cursor); }
                            }
                            KeyCode::Left => { if replace_cursor > 0 { replace_cursor -= 1; } }
                            KeyCode::Right => { if replace_cursor < replace_text.len() { replace_cursor += 1; } }
                            _ => {}
                        }
                        if key.modifiers.contains(KeyModifiers::CONTROL) && key.code == KeyCode::Char('u') {
                            if replace_mode != ReplaceMode::DeleteLine {
                                replace_text.clear();
                                replace_cursor = 0;
                            }
                        }
                    }
                    Focus::ResultList => {
                        match result_state {
                            ResultListState::FileList => {
                                match key.code {
                                    KeyCode::Tab => { focus = Focus::Search; }
                                    KeyCode::BackTab => { focus = Focus::Replace; }
                                    KeyCode::Char('j') | KeyCode::Down => {
                                        let visible: Vec<usize> = (0..search_results.len()).filter(|i| !deleted_files.contains(i)).collect();
                                        if visible.is_empty() { file_selected = None; }
                                        else {
                                            if let Some(sel) = file_selected {
                                                if let Some(pos) = visible.iter().position(|&v| v == sel) {
                                                    if pos + 1 < visible.len() { file_selected = Some(visible[pos+1]); }
                                                } else { file_selected = Some(visible[0]); }
                                            } else {
                                                file_selected = Some(visible[0]);
                                            }
                                        }
                                    }
                                    KeyCode::Char('k') | KeyCode::Up => {
                                        let visible: Vec<usize> = (0..search_results.len()).filter(|i| !deleted_files.contains(i)).collect();
                                        if visible.is_empty() { file_selected = None; }
                                        else {
                                            if let Some(sel) = file_selected {
                                                if let Some(pos) = visible.iter().position(|&v| v == sel) {
                                                    if pos > 0 { file_selected = Some(visible[pos-1]); }
                                                } else { file_selected = Some(visible[0]); }
                                            } else {
                                                file_selected = Some(visible[0]);
                                            }
                                        }
                                    }
                                    KeyCode::Char('g') | KeyCode::Char('h') | KeyCode::Left => {
                                        let visible: Vec<usize> = (0..search_results.len()).filter(|i| !deleted_files.contains(i)).collect();
                                        if !visible.is_empty() { file_selected = Some(visible[0]); }
                                    }
                                    KeyCode::Char('G') | KeyCode::Char('l') | KeyCode::Right => {
                                        let visible: Vec<usize> = (0..search_results.len()).filter(|i| !deleted_files.contains(i)).collect();
                                        if !visible.is_empty() { file_selected = Some(*visible.last().unwrap()); }
                                    }
                                    KeyCode::Enter => {
                                        if let Some(sel) = file_selected {
                                            if sel < search_results.len() {
                                                opened_file = Some(sel);
                                                result_state = ResultListState::LineList;
                                                line_selected = 0;
                                            }
                                        }
                                    }
                                    KeyCode::Char('r') => {
                                        if let Some(sel) = file_selected {
                                            if sel < search_results.len() && !deleted_files.contains(&sel) {
                                                let fr = &search_results[sel];
                                                perform_replace_file(fr, &search_text, &replace_text, search_mode, replace_mode, &deleted_lines.get(&sel).cloned().unwrap_or_default());
                                                notification = Some(("File replacement completed successfully".to_string(), std::time::Instant::now()));
                                                search_results = search_files(&project_root, &search_text, search_mode);
                                                deleted_files.clear();
                                                deleted_lines.clear();
                                                file_selected = None;
                                            }
                                        }
                                    }
                                    KeyCode::Char('d') => {
                                        if let Some(sel) = file_selected {
                                            if sel < search_results.len() {
                                                deleted_files.insert(sel);
                                                let visible: Vec<usize> = (0..search_results.len()).filter(|i| !deleted_files.contains(i)).collect();
                                                if visible.is_empty() { file_selected = None; }
                                                else {
                                                    // try to keep selection at same position
                                                    file_selected = Some(visible[0]);
                                                }
                                            }
                                        }
                                    }
                                    _ => {}
                                }
                            }
                            ResultListState::LineList => {
                                match key.code {
                                    KeyCode::Enter => { result_state = ResultListState::FileList; }
                                    KeyCode::Tab => { focus = Focus::Search; result_state = ResultListState::FileList; }
                                    KeyCode::BackTab => { focus = Focus::Replace; result_state = ResultListState::FileList; }
                                    KeyCode::Char('j') | KeyCode::Down => {
                                        if let Some(open_idx) = opened_file {
                                            if open_idx < search_results.len() {
                                                let fr = &search_results[open_idx];
                                                let deleted_set = deleted_lines.get(&open_idx);
                                                let filtered_count = fr.line_matches.iter().filter(|lm| {
                                                    if let Some(set) = deleted_set { !set.contains(&lm.line_number) } else { true }
                                                }).count();
                                                if line_selected + 1 < filtered_count { line_selected += 1; }
                                            }
                                        }
                                    }
                                    KeyCode::Char('k') | KeyCode::Up => { if line_selected > 0 { line_selected -= 1; } }
                                    KeyCode::Char('g') | KeyCode::Char('h') | KeyCode::Left => { line_selected = 0; }
                                    KeyCode::Char('G') | KeyCode::Char('l') | KeyCode::Right => {
                                        if let Some(open_idx) = opened_file {
                                            if open_idx < search_results.len() {
                                                let fr = &search_results[open_idx];
                                                let deleted_set = deleted_lines.get(&open_idx);
                                                let filtered_count = fr.line_matches.iter().filter(|lm| {
                                                    if let Some(set) = deleted_set { !set.contains(&lm.line_number) } else { true }
                                                }).count();
                                                if filtered_count > 0 { line_selected = filtered_count - 1; }
                                            }
                                        }
                                    }
                                    KeyCode::Char('r') => {
                                        if let Some(open_idx) = opened_file {
                                            if open_idx < search_results.len() {
                                                let fr = &search_results[open_idx];
                                                let deleted_set = deleted_lines.get(&open_idx);
                                                let filtered: Vec<&LineMatch> = fr.line_matches.iter().filter(|lm| {
                                                    if let Some(set) = deleted_set { !set.contains(&lm.line_number) } else { true }
                                                }).collect();
                                                if line_selected < filtered.len() {
                                                    let lm = filtered[line_selected];
                                                    perform_replace_line(fr, lm, &search_text, &replace_text, search_mode, replace_mode);
                                                    notification = Some(("Line replacement completed successfully".to_string(), std::time::Instant::now()));
                                                    search_results = search_files(&project_root, &search_text, search_mode);
                                                    result_state = ResultListState::FileList;
                                                    deleted_files.clear();
                                                    deleted_lines.clear();
                                                    file_selected = None;
                                                    opened_file = None;
                                                }
                                            }
                                        }
                                    }
                                    KeyCode::Char('d') => {
                                        if let Some(open_idx) = opened_file {
                                            if open_idx < search_results.len() {
                                                let fr = &search_results[open_idx];
                                                let deleted_set = deleted_lines.get(&open_idx);
                                                let filtered: Vec<&LineMatch> = fr.line_matches.iter().filter(|lm| {
                                                    if let Some(set) = deleted_set { !set.contains(&lm.line_number) } else { true }
                                                }).collect();
                                                if line_selected < filtered.len() {
                                                    let lm = filtered[line_selected];
                                                    let entry = deleted_lines.entry(open_idx).or_insert_with(HashSet::new);
                                                    entry.insert(lm.line_number);
                                                    let new_filtered_count = fr.line_matches.iter().filter(|lm2| {
                                                        if let Some(set) = deleted_lines.get(&open_idx) { !set.contains(&lm2.line_number) } else { true }
                                                    }).count();
                                                    if line_selected >= new_filtered_count && new_filtered_count > 0 { line_selected = new_filtered_count - 1; }
                                                    if new_filtered_count == 0 {
                                                        deleted_files.insert(open_idx);
                                                        result_state = ResultListState::FileList;
                                                        opened_file = None;
                                                    }
                                                }
                                            }
                                        }
                                    }
                                    _ => {}
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    terminal::disable_raw_mode()?;
    execute!(terminal.backend_mut(), terminal::LeaveAlternateScreen, event::DisableMouseCapture)?;
    Ok(())
}

fn perform_replace_file(fr: &FileResult, search_text: &str, replace_text: &str, search_mode: SearchMode, replace_mode: ReplaceMode, deleted_line_numbers: &HashSet<usize>) {
    if let Ok(content) = fs::read_to_string(&fr.path) {
        let mut new_lines = Vec::new();
        let mut regex_opt: Option<Regex> = None;
        if search_mode == SearchMode::Regex { if let Ok(r) = Regex::new(search_text) { regex_opt = Some(r); } }
        for (idx, line) in content.lines().enumerate() {
            if deleted_line_numbers.contains(&idx) { new_lines.push(line.to_string()); continue; }
            let matches = match search_mode {
                SearchMode::Simple => find_matches_simple(line, search_text, false, false),
                SearchMode::MatchCase => find_matches_simple(line, search_text, true, false),
                SearchMode::MatchWholeWord => find_matches_simple(line, search_text, false, true),
                SearchMode::MatchCaseWholeWord => find_matches_simple(line, search_text, true, true),
                SearchMode::Regex => { if let Some(ref re) = regex_opt { find_matches_regex(line, re) } else { vec![] } }
            };
            if matches.is_empty() { new_lines.push(line.to_string()); }
            else {
                if replace_mode == ReplaceMode::DeleteLine { continue; }
                else { let new_line = replace_line_content(line, &matches, replace_text, replace_mode); new_lines.push(new_line); }
            }
        }
        let final_content = if content.ends_with('\n') { new_lines.join("\n") + "\n" } else { new_lines.join("\n") };
        let _ = fs::write(&fr.path, final_content);
    }
}

fn perform_replace_line(fr: &FileResult, lm: &LineMatch, search_text: &str, replace_text: &str, search_mode: SearchMode, replace_mode: ReplaceMode) {
    if let Ok(content) = fs::read_to_string(&fr.path) {
        let mut new_lines = Vec::new();
        let mut regex_opt: Option<Regex> = None;
        if search_mode == SearchMode::Regex { if let Ok(r) = Regex::new(search_text) { regex_opt = Some(r); } }
        for (idx, line) in content.lines().enumerate() {
            if idx == lm.line_number {
                if replace_mode == ReplaceMode::DeleteLine { continue; }
                else {
                    let matches = match search_mode {
                        SearchMode::Simple => find_matches_simple(line, search_text, false, false),
                        SearchMode::MatchCase => find_matches_simple(line, search_text, true, false),
                        SearchMode::MatchWholeWord => find_matches_simple(line, search_text, false, true),
                        SearchMode::MatchCaseWholeWord => find_matches_simple(line, search_text, true, true),
                        SearchMode::Regex => { if let Some(ref re) = regex_opt { find_matches_regex(line, re) } else { vec![] } }
                    };
                    let new_line = replace_line_content(line, &matches, replace_text, replace_mode);
                    new_lines.push(new_line);
                }
            } else { new_lines.push(line.to_string()); }
        }
        let final_content = if content.ends_with('\n') { new_lines.join("\n") + "\n" } else { new_lines.join("\n") };
        let _ = fs::write(&fr.path, final_content);
    }
}

fn perform_replace_all(_project_root: &Path, results: &[FileResult], search_text: &str, replace_text: &str, search_mode: SearchMode, replace_mode: ReplaceMode, deleted_files: &HashSet<usize>, deleted_lines: &HashMap<usize, HashSet<usize>>) {
    let mut regex_opt: Option<Regex> = None;
    if search_mode == SearchMode::Regex { if let Ok(r) = Regex::new(search_text) { regex_opt = Some(r); } }
    for (file_idx, fr) in results.iter().enumerate() {
        if deleted_files.contains(&file_idx) { continue; }
        let deleted_set = deleted_lines.get(&file_idx);
        if let Ok(content) = fs::read_to_string(&fr.path) {
            let mut new_lines = Vec::new();
            for (line_idx, line) in content.lines().enumerate() {
                if let Some(set) = deleted_set { if set.contains(&line_idx) { new_lines.push(line.to_string()); continue; } }
                let matches = match search_mode {
                    SearchMode::Simple => find_matches_simple(line, search_text, false, false),
                    SearchMode::MatchCase => find_matches_simple(line, search_text, true, false),
                    SearchMode::MatchWholeWord => find_matches_simple(line, search_text, false, true),
                    SearchMode::MatchCaseWholeWord => find_matches_simple(line, search_text, true, true),
                    SearchMode::Regex => { if let Some(ref re) = regex_opt { find_matches_regex(line, re) } else { vec![] } }
                };
                if matches.is_empty() { new_lines.push(line.to_string()); }
                else {
                    if replace_mode == ReplaceMode::DeleteLine { continue; }
                    else { let new_line = replace_line_content(line, &matches, replace_text, replace_mode); new_lines.push(new_line); }
                }
            }
            let final_content = if content.ends_with('\n') { new_lines.join("\n") + "\n" } else { new_lines.join("\n") };
            let _ = fs::write(&fr.path, final_content);
        }
    }
}

fn centered_rect(percent_x: u16, percent_y: u16, r: Rect) -> Rect {
    let popup_layout = Layout::default().direction(Direction::Vertical).constraints([Constraint::Percentage((100 - percent_y) / 2), Constraint::Percentage(percent_y), Constraint::Percentage((100 - percent_y) / 2)]).split(r);
    Layout::default().direction(Direction::Horizontal).constraints([Constraint::Percentage((100 - percent_x) / 2), Constraint::Percentage(percent_x), Constraint::Percentage((100 - percent_x) / 2)]).split(popup_layout[1])[1]
}
